'use client';
import { useCallback, useEffect, useId, useRef, useState, type FocusEvent, type KeyboardEvent, type PointerEvent } from 'react';
import { spring, useRafLoop, useStudioMotion } from '../../motion';
import type { EffectProps } from '../../types';
import { DotField, mixRgb, toRgb, type Influence, type Palette } from './field';
import styles from './styles.module.css';

type Params = { spacing: number; dotSize: number; radius: number; strength: number; ripple: boolean };

const BUCKETS = 5;

/** Re-render trigger when the theme changes (data-theme/class/style on <html>, or the OS colour scheme). */
function useThemeVersion(): number {
  const [v, setV] = useState(0);
  useEffect(() => {
    const bump = () => setV((n) => n + 1);
    const mo = new MutationObserver(bump);
    mo.observe(document.documentElement, { attributes: true, attributeFilter: ['data-theme', 'class', 'style'] });
    const mq = window.matchMedia?.('(prefers-color-scheme: dark)');
    mq?.addEventListener('change', bump);
    return () => { mo.disconnect(); mq?.removeEventListener('change', bump); };
  }, []);
  return v;
}

export default function DotGridPointerField({ params }: EffectProps<Params>) {
  const { reduced } = useStudioMotion();
  const hintId = useId();
  const wrap = useRef<HTMLDivElement>(null);
  const canvas = useRef<HTMLCanvasElement>(null);
  const field = useRef(new DotField());
  const view = useRef({ dpr: 1, palette: { dots: ['#5c5a52'], focus: '#1d4ed8' } as Palette });
  const pointer = useRef<Influence | null>(null);
  const cursor = useRef<Influence | null>(null); // keyboard-driven influence point (drawn as a ring)
  const [active, setActive] = useState(false);
  const theme = useThemeVersion();
  const opts = useRef(params);
  opts.current = params;

  const paint = useCallback(() => {
    const ctx = canvas.current?.getContext('2d');
    if (!ctx) return;
    field.current.draw(ctx, view.current.dpr, opts.current.dotSize, view.current.palette, cursor.current);
  }, []);

  // Colours from the theme tokens, resolved on the element itself (so an always-dark stage is respected too).
  useEffect(() => {
    const el = canvas.current;
    const ctx = el?.getContext('2d');
    if (!el || !ctx) return;
    const cs = getComputedStyle(el);
    const base = toRgb(ctx, cs.getPropertyValue('--mk-ink-muted').trim(), '#5c5a52');
    const hot = toRgb(ctx, cs.getPropertyValue('--mk-signal').trim(), '#bf2f09');
    const dots = Array.from({ length: BUCKETS }, (_, b) => mixRgb(base, hot, b / (BUCKETS - 1)));
    ctx.fillStyle = '#1d4ed8';
    ctx.fillStyle = cs.getPropertyValue('--mk-focus').trim() || '#1d4ed8';
    view.current.palette = { dots, focus: String(ctx.fillStyle) };
    paint();
  }, [theme, paint]);

  // Size (DPR ≤ 2) and re-layout on every resize of the box; spacing changes rebuild the grid too.
  useEffect(() => {
    const box = wrap.current, el = canvas.current;
    if (!box || !el || typeof ResizeObserver === 'undefined') return;
    const ro = new ResizeObserver(() => {
      const w = box.clientWidth, h = box.clientHeight;
      if (!w || !h) return;
      const dpr = Math.min(2, window.devicePixelRatio || 1);
      view.current.dpr = dpr;
      el.width = Math.round(w * dpr); el.height = Math.round(h * dpr);
      field.current.layout(w, h, opts.current.spacing);
      if (cursor.current) cursor.current = { x: Math.min(w, cursor.current.x), y: Math.min(h, cursor.current.y) };
      paint();
    });
    ro.observe(box);
    return () => ro.disconnect();
  }, [params.spacing, paint]);

  useEffect(() => { paint(); }, [params.dotSize, paint]);

  // The loop runs only while something moves; it stops itself once every spring has settled.
  useRafLoop(wrap, (dt) => {
    const f = field.current;
    let rest = false;
    for (let left = dt; left > 1e-6; left -= 1 / 120) rest = f.step(Math.min(left, 1 / 120), pointer.current ?? cursor.current, opts.current, spring.release);
    paint();
    if (rest) setActive(false);
  }, active && !reduced);

  const wake = () => { if (!reduced) setActive(true); };
  const local = (e: PointerEvent<HTMLDivElement>): Influence => {
    const r = e.currentTarget.getBoundingClientRect();
    return { x: e.clientX - r.left, y: e.clientY - r.top };
  };
  const ripple = (at: Influence) => {
    if (reduced || !params.ripple) return;
    const f = field.current;
    f.ripples = [...f.ripples.slice(-3), { ...at, age: 0 }];
    wake();
  };

  const onPointerMove = (e: PointerEvent<HTMLDivElement>) => { if (reduced) return; pointer.current = local(e); wake(); };
  const onPointerLeave = () => { pointer.current = null; wake(); };
  const onPointerDown = (e: PointerEvent<HTMLDivElement>) => ripple(local(e));

  const onFocus = (e: FocusEvent<HTMLDivElement>) => {
    if (reduced || !e.currentTarget.matches(':focus-visible')) return;
    cursor.current = { x: field.current.w / 2, y: field.current.h / 2 };
    wake();
  };
  const onBlur = () => { cursor.current = null; wake(); paint(); };
  const onKeyDown = (e: KeyboardEvent<HTMLDivElement>) => {
    if (reduced) return;
    const f = field.current;
    const stepPx = params.spacing * (e.shiftKey ? 4 : 1);
    const c = cursor.current ?? { x: f.w / 2, y: f.h / 2 };
    let used = true;
    switch (e.key) {
      case 'ArrowLeft': cursor.current = { x: Math.max(0, c.x - stepPx), y: c.y }; break;
      case 'ArrowRight': cursor.current = { x: Math.min(f.w, c.x + stepPx), y: c.y }; break;
      case 'ArrowUp': cursor.current = { x: c.x, y: Math.max(0, c.y - stepPx) }; break;
      case 'ArrowDown': cursor.current = { x: c.x, y: Math.min(f.h, c.y + stepPx) }; break;
      case 'Enter': case ' ': cursor.current = c; ripple(c); break;
      case 'Escape': cursor.current = null; break;
      default: used = false;
    }
    if (used) { e.preventDefault(); wake(); paint(); }
  };

  return (
    <div className={styles.root}>
      <div
        ref={wrap}
        className={styles.field}
        tabIndex={reduced ? undefined : 0}
        role={reduced ? 'img' : 'application'}
        aria-label={reduced ? 'Dot grid (static: motion is reduced)' : 'Interactive dot field'}
        aria-describedby={hintId}
        aria-keyshortcuts={reduced ? undefined : 'ArrowLeft ArrowRight ArrowUp ArrowDown Enter Escape'}
        onPointerMove={onPointerMove}
        onPointerLeave={onPointerLeave}
        onPointerDown={onPointerDown}
        onFocus={onFocus}
        onBlur={onBlur}
        onKeyDown={onKeyDown}
      >
        <canvas ref={canvas} className={styles.canvas} aria-hidden="true" />
      </div>
      <div className={styles.bar}>
        <p id={hintId} className={styles.hint}>
          {reduced
            ? 'Motion is reduced, so the grid stays still.'
            : `Move the pointer through the field${params.ripple ? ' and click to send a ripple' : ''}. Keyboard: focus the field, arrows move the influence${params.ripple ? ', Enter sends a ripple' : ''}, Esc clears it.`}
        </p>
        {params.ripple && !reduced ? (
          <button type="button" className={styles.button} onClick={() => ripple({ x: field.current.w / 2, y: field.current.h / 2 })}>
            <svg viewBox="0 0 16 16" aria-hidden="true" focusable="false"><circle cx="8" cy="8" r="2" /><circle cx="8" cy="8" r="6" /></svg>
            Send ripple
          </button>
        ) : null}
      </div>
    </div>
  );
}

/**
 * Dot field simulation + drawing (framework-free). Every dot is a damped spring pulled towards a target offset
 * that the pointer and the ripples define; the loop can stop as soon as every spring has settled.
 */
import type { SpringConfig } from '../../motion';

export interface Ripple { x: number; y: number; age: number }
export interface Influence { x: number; y: number }

export interface FieldOptions { spacing: number; dotSize: number; radius: number; strength: number }

export interface Palette { dots: string[]; focus: string }

const TAU = Math.PI * 2;
export const RIPPLE_SPEED = 460; // px/s
export const RIPPLE_LIFE = 1.35; // s
const RIPPLE_WIDTH = 34; // px

export class DotField {
  w = 0; h = 0; n = 0;
  bx = new Float32Array(0); by = new Float32Array(0);
  ox = new Float32Array(0); oy = new Float32Array(0); vx = new Float32Array(0); vy = new Float32Array(0);
  sc = new Float32Array(0); vs = new Float32Array(0); heat = new Float32Array(0);
  ripples: Ripple[] = [];

  /** Lay out a centred grid for a w × h CSS-pixel box. Motion state is reset (a resize is a new field). */
  layout(w: number, h: number, spacing: number): void {
    this.w = w; this.h = h;
    const cols = Math.max(1, Math.floor((w - spacing) / spacing) + 1);
    const rows = Math.max(1, Math.floor((h - spacing) / spacing) + 1);
    const x0 = (w - (cols - 1) * spacing) / 2, y0 = (h - (rows - 1) * spacing) / 2;
    const n = cols * rows;
    this.n = n;
    this.bx = new Float32Array(n); this.by = new Float32Array(n);
    this.ox = new Float32Array(n); this.oy = new Float32Array(n); this.vx = new Float32Array(n); this.vy = new Float32Array(n);
    this.sc = new Float32Array(n).fill(1); this.vs = new Float32Array(n); this.heat = new Float32Array(n);
    for (let r = 0, i = 0; r < rows; r++) for (let c = 0; c < cols; c++, i++) { this.bx[i] = x0 + c * spacing; this.by[i] = y0 + r * spacing; }
    this.ripples = [];
  }

  /** Advance `dt` seconds. Returns true when every dot is at rest and no ripple is alive. */
  step(dt: number, pointer: Influence | null, o: FieldOptions, spring: SpringConfig): boolean {
    for (const r of this.ripples) r.age += dt;
    this.ripples = this.ripples.filter((r) => r.age < RIPPLE_LIFE);
    const { stiffness: k, damping: c, mass: m } = spring;
    const R = o.radius, R2 = R * R;
    let restless = this.ripples.length > 0;
    for (let i = 0; i < this.n; i++) {
      const bx = this.bx[i], by = this.by[i];
      let tx = 0, ty = 0, ts = 1, heat = 0;
      if (pointer) {
        const dx = bx - pointer.x, dy = by - pointer.y, d2 = dx * dx + dy * dy;
        if (d2 < R2) {
          const d = Math.sqrt(d2) || 1e-3;
          const q = 1 - d2 / R2, f = q * q; // smooth (Wendland-like) falloff, 0 at the radius
          tx += (dx / d) * o.strength * f; ty += (dy / d) * o.strength * f;
          ts += 1.5 * f; heat += f;
        }
      }
      for (const r of this.ripples) {
        const dx = bx - r.x, dy = by - r.y, d = Math.sqrt(dx * dx + dy * dy) || 1e-3;
        const g = Math.exp(-(((d - r.age * RIPPLE_SPEED) / RIPPLE_WIDTH) ** 2));
        if (g < 0.01) continue;
        const life = 1 - r.age / RIPPLE_LIFE, a = g * life * life;
        tx += (dx / d) * o.strength * 0.9 * a; ty += (dy / d) * o.strength * 0.9 * a;
        ts += 1.1 * a; heat += a;
      }
      // Semi-implicit Euler, substepped by the caller.
      this.vx[i] += ((-k * (this.ox[i] - tx) - c * this.vx[i]) / m) * dt; this.ox[i] += this.vx[i] * dt;
      this.vy[i] += ((-k * (this.oy[i] - ty) - c * this.vy[i]) / m) * dt; this.oy[i] += this.vy[i] * dt;
      this.vs[i] += ((-k * (this.sc[i] - ts) - c * this.vs[i]) / m) * dt; this.sc[i] += this.vs[i] * dt;
      this.heat[i] += (Math.min(1, heat) - this.heat[i]) * Math.min(1, dt * 14);
      if (!restless && (Math.abs(this.ox[i] - tx) > 0.02 || Math.abs(this.oy[i] - ty) > 0.02 || Math.abs(this.vx[i]) > 0.05 || Math.abs(this.vy[i]) > 0.05
        || Math.abs(this.sc[i] - ts) > 0.002 || Math.abs(this.vs[i]) > 0.01 || Math.abs(this.heat[i] - Math.min(1, heat)) > 0.004)) restless = true;
    }
    return !restless;
  }

  /** Draw with one path per tint bucket (≤ 5 fills per frame, no per-dot style changes). */
  draw(ctx: CanvasRenderingContext2D, dpr: number, dotSize: number, palette: Palette, cursor: Influence | null): void {
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    ctx.clearRect(0, 0, this.w, this.h);
    const buckets = palette.dots.length;
    for (let b = 0; b < buckets; b++) {
      ctx.beginPath();
      let any = false;
      for (let i = 0; i < this.n; i++) {
        const level = Math.min(buckets - 1, Math.floor(this.heat[i] * buckets * 0.999 + 0.25));
        if (level !== b) continue;
        const x = this.bx[i] + this.ox[i], y = this.by[i] + this.oy[i], r = Math.max(0.3, dotSize * this.sc[i]);
        ctx.moveTo(x + r, y);
        ctx.arc(x, y, r, 0, TAU);
        any = true;
      }
      if (any) { ctx.fillStyle = palette.dots[b]; ctx.fill(); }
    }
    if (cursor) {
      ctx.beginPath();
      ctx.arc(cursor.x, cursor.y, 11, 0, TAU);
      ctx.lineWidth = 2;
      ctx.strokeStyle = palette.focus;
      ctx.stroke();
    }
  }
}

/** Parse any CSS colour the 2D context understands into [r, g, b]. */
export function toRgb(ctx: CanvasRenderingContext2D, css: string, fallback: string): [number, number, number] {
  ctx.fillStyle = fallback;
  if (css) ctx.fillStyle = css;
  const v = String(ctx.fillStyle);
  if (v.startsWith('#')) return [parseInt(v.slice(1, 3), 16), parseInt(v.slice(3, 5), 16), parseInt(v.slice(5, 7), 16)];
  const m = v.match(/[\d.]+/g);
  return m ? [Number(m[0]), Number(m[1]), Number(m[2])] : [0, 0, 0];
}

export const mixRgb = (a: [number, number, number], b: [number, number, number], t: number): string =>
  `rgb(${Math.round(a[0] + (b[0] - a[0]) * t)} ${Math.round(a[1] + (b[1] - a[1]) * t)} ${Math.round(a[2] + (b[2] - a[2]) * t)})`;

.root {
  container-type: inline-size;
  width: 100%;
  align-self: stretch;
  display: grid;
  grid-template-rows: 1fr auto;
  font-family: var(--mk-font-text, ui-sans-serif, system-ui, sans-serif);
  color: var(--mk-ink, #11110f);
}

.field {
  position: relative;
  min-height: clamp(280px, 52cqi, 440px);
  cursor: crosshair;
  touch-action: pan-y;
  outline: none;
}
.field:focus-visible { outline: 2px solid var(--mk-focus, #1d4ed8); outline-offset: -4px; }
.field[role='img'] { cursor: default; }
.canvas { position: absolute; inset: 0; width: 100%; height: 100%; display: block; }

.bar {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 10px 20px;
  padding: 12px clamp(12px, 3cqi, 24px);
  border-top: 1px solid var(--mk-line, #11110f24);
}
.hint { margin: 0; max-width: 62ch; font-size: 0.8125rem; line-height: 1.45; color: var(--mk-ink-muted, #5c5a52); }

.button {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  min-height: 44px;
  padding: 0 18px 0 14px;
  border: 1px solid var(--mk-line-strong, #11110f);
  border-radius: 999px;
  background: transparent;
  color: inherit;
  font: inherit;
  font-size: 0.875rem;
  font-weight: 500;
  cursor: pointer;
  transition: background-color var(--mk-duration-fast, 160ms) var(--mk-ease-standard, ease), color var(--mk-duration-fast, 160ms) var(--mk-ease-standard, ease);
}
.button svg { width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 1.5; }
.button:hover { background: var(--mk-ink, #11110f); color: var(--mk-surface, #fbf9f4); }
.button:focus-visible { outline: 2px solid var(--mk-focus, #1d4ed8); outline-offset: 2px; }

@media (prefers-reduced-motion: reduce) {
  .button { transition: none; }
}
